/*selectMasterMdCmChemicalMatMngList*/ SELECT REQ.REQ_NO ,REQ.BYIT_COMORG_CODE ,REQ.BUYER ,(SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = REQ.BUYER) AS BUYER_NM ,REQ.AGENT ,(SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = REQ.AGENT) AS AGENT_NM ,REQ.BUYER_ITEM_NO ,DECODE(D.DESCRIPTION, NULL, B.DESCRIPTION_LOC, D.DESCRIPTION) AS DESCRIPTION_LOC ,DECODE(D.SPECIFICATION, NULL, B.SPECIFICATION, D.SPECIFICATION) AS SPECIFICATION ,DECODE(D.MAKER_NAME, NULL, B.MAKER_NAME, D.MAKER_NAME) AS MAKER_NAME ,REQ.REQ_DATE ,REQ.REQ_USER_ID ,C.USER_NAME_LOC ,C.PHONE_NUMBER ,REQ.REQ_STATUS ,REQ.STOA_DATE ,REQ.STOA_USER_ID ,(SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = REQ.STOA_USER_ID) AS STOA_USER_NM ,REQ.ATOB_DATE ,(SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = REQ.ATOB_USER_ID) AS ATOB_USER_NM ,REQ.CONFIRM_DATE ,(SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = REQ.CONFIRM_USER_ID) AS CONFIRM_USER_NM ,(SELECT DECODE(COUNT(PO_NO),0,'N','Y') FROM ICOMPODT PODT WHERE PODT.BUYER = REQ.BUYER AND PODT.BUYER_ITEM_NO = REQ.BUYER_ITEM_NO AND PODT.ADD_DATE BETWEEN TO_CHAR(SYSDATE-30,'YYYYMMDD') AND TO_CHAR(SYSDATE,'YYYYMMDD') AND PODT.STATUS != 'D') AS PO_YN , DECODE(TRIM(REQ.CMC_HARMFUL_YN),'','0','1') AS MAKE_IMG ,(SELECT TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'CM01' AND COD.CODE = REQ.REQ_STATUS) AS STATUS_NM ,REQ.CHANGE_DATE ,REQ.CHANGE_USER_ID ,(SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = REQ.CHANGE_USER_ID) AS CHANGE_USER_NM ,REQ.QUOTATION_NO ,REQ.QUOTATION_SEQ ,REQ.REVISION ,(SELECT DECODE(COUNT(COD.CODE),0,'N','Y') FROM ICOMCOD1 COD WHERE 1=1 AND COD.CODE = B.CMS_CATEG_ID AND COD.TYPE = 'CM11' AND COD.TEXT1 = 'Y' AND COD.FLAG = 'Y') AS SG118_YN FROM KEP_CMC_REQ REQ, ICOMBYIT B, ICOMLUSR C, KEPRQDT D WHERE REQ.BYIT_COMORG_CODE = B.BUYER(+) AND REQ.BUYER_ITEM_NO = B.BUYER_ITEM_NO(+) AND REQ.REQ_USER_ID = C.USER_ID AND B.STATUS(+) != 'D'
AND REQ.BUYER = D.BUYER(+) AND REQ.QUOTATION_NO = D.QUOTATION_NO(+) AND REQ.QUOTATION_SEQ = D.QUOTATION_SEQ(+)
AND TO_CHAR(REQ.REQ_DATE,'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND UPPER(REQ.REQ_NO) LIKE UPPER(#{st_req_no}) || '%'
AND UPPER(REQ.BUYER_ITEM_NO) LIKE UPPER(#{st_buyer_item_no}) || '%'
AND REQ.REQ_STATUS NOT IN ('N', 'D')
AND REQ.REQ_STATUS = #{st_status}
AND REQ.BUYER = #{st_buyer_code}
AND REQ.AGENT = #{st_agent_code}
AND (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = REQ.REQ_USER_ID) LIKE '%' || #{st_add_usr_id} || '%'
AND REQ.REQ_STATUS IN ('Q','S','R','P','A')
AND ( UPPER(B.DESCRIPTION_LOC) LIKE UPPER('%'||#{st_description}||'%') OR UPPER(D.DESCRIPTION) LIKE UPPER('%'||#{st_description}||'%'))
AND ( UPPER(B.SPECIFICATION) LIKE UPPER('%'||#{st_specification}||'%') OR UPPER(D.SPECIFICATION) LIKE UPPER('%'||#{st_specification}||'%'))
AND ( UPPER(B.MAKER_NAME) LIKE UPPER('%'||#{st_maker_name}||'%') OR UPPER(D.MAKER_NAME) LIKE UPPER('%'||#{st_maker_name}||'%'))
AND UPPER(REQ.QUOTATION_NO) LIKE UPPER('%'||#{st_quotation_no}||'%')
ORDER BY REQ.REQ_NO

