		     /*reqMasterrMdCtChemicalMat*/
                   UPDATE KEP_CMC_REQ REQ
                   SET REQ_STATUS = #{st_status}  
                     , MSDS_NO = #{st_msds_no}
                     , MSDS_NO_FILEKEY = #{st_msds_file_key}
                     , CMC_HARMFUL_YN = #{st_harmful_yn}
                     , CMC_USE_CODE = DECODE(#{st_harmful_yn},'Y',#{st_use_cd},NULL)
                     , CMC_INFO_LEVEL = DECODE(#{st_harmful_yn},'Y',#{st_info_level},NULL)
                     , CMC_INFO_UNIT = DECODE(#{st_harmful_yn},'Y',#{st_info_unit},NULL)
                     , KEP_NOTE = #{st_kep_note}
                     , KEP_CMC_NOTE= #{st_kep_cmc_note}
                     , TEMP_COND = #{st_temp_cond}
                     , TEMP_RANGE = REPLACE(#{st_temp_range}, '''')
                     , CHANGE_DATE = SYSDATE
                     , CHANGE_USER_ID = #{USER_ID}
                 WHERE REQ.REQ_NO = #{st_req_no}


		     /*updateStatusMasterrMdCtChemicalMat*/
                   UPDATE KEP_CMC_REQ REQ
                   SET REQ_STATUS = #{st_status}  
                     , CHANGE_DATE = SYSDATE
                     , CHANGE_USER_ID =#{USER_ID}
                 WHERE REQ.REQ_NO =#{st_req_no}


		     /*saveMasterrMdCtAtobChemicalMat*/
                   UPDATE KEP_CMC_REQ REQ
                   SET REQ_STATUS = #{st_status}  
                     , ATOB_DATE = SYSDATE
                     , ATOB_USER_ID =#{USER_ID}
                     , CHANGE_DATE = SYSDATE
                     , CHANGE_USER_ID =#{USER_ID}
                 WHERE REQ.REQ_NO =#{st_req_no}


		     /*confirmMasterrMdCtChemicalMat*/
                   UPDATE KEP_CMC_REQ REQ
                   SET REQ_STATUS = #{st_status}  
                     , CONFIRM_DATE = SYSDATE
                     , CONFIRM_USER_ID =#{USER_ID}
                     , CHANGE_DATE = SYSDATE
                     , CHANGE_USER_ID =#{USER_ID}
                 WHERE REQ.REQ_NO =#{st_req_no}


		     /*deleteMasterrMdCtChemicalMat1*/
                   UPDATE KEP_CMC_BYIT BYIT
                   SET STATUS = 'D'  
                     , CHANGE_DATE = SYSDATE
                     , CHANGE_USER_ID =#{USER_ID}
                 WHERE BYIT.BYIT_COMORG_CODE =#{st_byit_comorg_code}
                 AND BYIT.BUYER_ITEM_NO =#{st_buyer_item_no}
                 AND BYIT.STATUS != 'D'


		     /*deleteMasterrMdCtChemicalMat2*/
                   UPDATE KEP_CMC_BYIT_MAKE MAK
                   SET STATUS = 'D'  
                     , CHANGE_DATE = SYSDATE
                     , CHANGE_USER_ID =#{USER_ID}
                 WHERE MAK.BYIT_COMORG_CODE =#{st_byit_comorg_code}
                 AND MAK.BUYER_ITEM_NO =#{st_buyer_item_no}
                 AND MAK.STATUS != 'D'

