/*selectMasterMdCmKepCmcSeq*/
SELECT NVL(COUNT(A.SEQ),0)+1  AS CMC_SEQ
FROM KEP_CMC_BYIT A 
WHERE A.BYIT_COMORG_CODE =#{st_byit_comorg_code}
AND A.BUYER_ITEM_NO = #{st_buyer_item_no}

