/* confirmMasterrMdCtChemicalMat2 */
INSERT INTO KEP_CMC_BYIT_MAKE
(
	BYIT_COMORG_CODE
	, BUYER_ITEM_NO
	, SEQ
	, CMC_HARMFUL_YN
	, STATUS
	, OPEN_FLAG
	, CAS_NO
	, COMPONENT_TYPE_CODE
	, MIN_MAKE_RATE
	, MAX_MAKE_RATE
	, AVG_MAKE_RATE
	, CML_HARMFUL_YN
	, CML_PRE_TROUBLE_YN
	, CML_BAN_OBJECT_YN
	, CML_LIMIT_OBJECT_YN
	, ADD_DATE
	, ADD_USER_ID
	, CHANGE_DATE
	, CHANGE_USER_ID
) VALUES
(
	#{st_byit_comorg_code}
	,#{st_buyer_item_no}
	, #{CMC_SEQ}
	, #{st_harmful_yn}
	, 'C'
	, #{OPEN_FLAG}
	, #{CAS_NO}
	, #{COMPONENT_TYPE_CODE}
	, #{MIN_MAKE_RATE}
	, #{MAX_MAKE_RATE}
	, #{AVG_MAKE_RATE}
	, DECODE(#{CML_HARMFUL_YN},'0','N','Y')
	, DECODE(#{CML_PRE_TROUBLE_YN},'0','N','Y')
	, DECODE(#{CML_BAN_OBJECT_YN},'0','N','Y')
	, DECODE(#{CML_LIMIT_OBJECT_YN},'0','N','Y')
	, SYSDATE
	, #{USER_ID}
	, SYSDATE
	, #{USER_ID}
)


