/* confirmMasterrMdCtChemicalMat4 */
UPDATE ICOMBYIT A
SET MSDS_NO = DECODE(#{st_msds_no}, 'MS88888888', '', #{st_msds_no})
 , MATERIAL_TYPE = DECODE(#{st_harmful_yn},'Y','H',NULL)
 , MSDS_YN = 'Y'
 , TEMP_COND = #{st_temp_cond}
 , TEMP_RANGE = REPLACE(#{st_temp_range}, '''')
 WHERE A.BUYER = #{st_byit_comorg_code}
 AND A.BUYER_ITEM_NO = #{st_buyer_item_no}


/* confirmMasterrMdCtChemicalMat5 */
UPDATE	KEPRQDT A
SET		MSDS_NO = #{st_msds_no},
		MSDS_YN = 'Y',
		MSDS_USER_ID = #{USER_ID},
		MSDS_A_CONFIRM_ID = #{USER_ID},
		MSDS_STATUS = 'C'
WHERE	A.BUYER = #{st_buyer}
AND		A.QUOTATION_NO = #{st_quotation_no}
AND		A.QUOTATION_SEQ = #{st_quotation_seq}
AND		A.REVISION = #{st_revision}


/*afterMasterrMdCtChemicalMat2*/
UPDATE	KEPRQDT
SET		MSDS_NO = #{st_msds_no},
		MSDS_YN = 'Y',
		MSDS_USER_ID = #{USER_ID},
		MSDS_A_CONFIRM_ID = #{USER_ID},
		MSDS_STATUS = 'C'
WHERE	1=1
AND		BUYER = #{st_buyer}
AND		QUOTATION_NO = #{st_quotation_no}
AND		QUOTATION_SEQ = #{st_quotation_seq}
AND		REVISION = #{st_revision}


/*afterMasterrMdCtChemicalMat3*/
UPDATE	KEP_CMC_REQ A
SET		A.REQ_STATUS = 'N',
		A.KEP_CMC_NOTE = #{st_kep_cmc_note} || ' ' || TO_CHAR(SYSDATE, 'YYYY/MM/DD HH24:MI') || ' ' || '중복품목 요청건 처리로 인한 일괄 취소',
		A.CHANGE_DATE = SYSDATE,
		A.CHANGE_USER_ID =#{USER_ID}
WHERE	1=1
AND		A.REQ_NO IN (SELECT B.REQ_NO FROM KEP_CMC_REQ B WHERE (B.BUYER, B.QUOTATION_NO, B.QUOTATION_SEQ, B.REVISION) IN (SELECT BUYER, QUOTATION_NO, QUOTATION_SEQ, REVISION FROM KEP_CMC_REQ WHERE REQ_NO = #{st_req_no}))
AND		A.REQ_NO <> #{st_req_no}
AND		A.REQ_STATUS NOT IN ('B', 'C', 'D', 'N', 'T')
